const now = new Date();
const pad = (value) => String(value).padStart(2, "0");
const weekdayNames = ["\uC77C\uC694\uC77C", "\uC6D4\uC694\uC77C", "\uD654\uC694\uC77C", "\uC218\uC694\uC77C", "\uBAA9\uC694\uC77C", "\uAE08\uC694\uC77C", "\uD1A0\uC694\uC77C"];
const year = String(now.getFullYear());
const month = pad(now.getMonth() + 1);
const day = pad(now.getDate());
const weekdayIndex = now.getDay();
const isWeekend = weekdayIndex === 0 || weekdayIndex === 6;
return [{
  json: {
    todayDate: `${year}-${month}-${day}`,
    todayInt: `${year}${month}${day}`,
    todayMMDD: `${month}${day}`,
    WeekdayName: weekdayNames[weekdayIndex],
    IsWeekend: isWeekend,
    DefaultIsHoliday: isWeekend,
    DefaultHolidayName: isWeekend ? '\uC8FC\uB9D0' : '\uD3C9\uC77C',
  }
}];

const baseline = $('Weekday Baseline').first()?.json ?? {};
const dbPayload = $('Holiday DB Fallback').first()?.json ?? {};
const dbFound = !dbPayload.error && [true, 1, '1', 'true'].includes(dbPayload.found_in_db);
let isHoliday = !!baseline.DefaultIsHoliday;
let holidayName = baseline.DefaultHolidayName || (isHoliday ? '\uC8FC\uB9D0' : '\uD3C9\uC77C');
let holidayLookupSource = isHoliday ? 'default-weekend' : 'default-weekday';
if (dbFound) {
  isHoliday = true;
  holidayName = String(dbPayload.holiday_name || '\uACF5\uD734\uC77C');
  holidayLookupSource = dbPayload.source_type ? `db:${dbPayload.source_type}` : 'db';
}
return [{
  json: {
    today_date: baseline.todayDate || "",
    is_holiday: isHoliday,
    holiday_name: holidayName,
    holiday_lookup_source: holidayLookupSource,
    is_weekend: !!baseline.IsWeekend,
    db_error: dbPayload.error || '',
  }
}];

const raw = $('Inbox Child Folders').first()?.json ?? {};
const folders = Array.isArray(raw.value) ? raw.value : [];
const targetName = '01. \uB77C\uC774\uC120\uC2A4 \uC694\uCCAD';
const normalize = (value) => String(value ?? '').normalize('NFC').replace(/\\s+/g, '').toLowerCase();
const target = folders.find((folder) => normalize(folder.displayName) === normalize(targetName));
return [{ json: {
  folderFound: Boolean(target),
  folderId: target?.id || '',
  folderName: target?.displayName || '',
  folderError: raw.error?.message || raw.error?.description || raw.error || "",
} }];

const holiday = $('Determine Holiday').first()?.json ?? {};
const folderInfo = $('Resolve License Folder').first()?.json ?? {};
const inboxPayload = $('Inbox Messages').first()?.json ?? {};
const folderPayload = $('License Folder Messages').first()?.json ?? {};
const vacationItems = $('Vacation Calendar').all();

const K = {
  approval: '\uC2B9\uC778\uD544\uC694',
  folderName: '01. \uB77C\uC774\uC120\uC2A4 \uC694\uCCAD',
  license1: '\uB77C\uC774\uC120\uC2A4',
  license2: 'license',
  license3: '\uB77C\uC774\uC13C\uC2A4',
  vacation1: '\uD734\uAC00',
  vacation2: '\uC5F0\uCC28',
  vacation3: '\uBC18\uCC28',
  vacation4: '\uC624\uC804\uBC18\uCC28',
  vacation5: '\uC624\uD6C4\uBC18\uCC28',
  vacation6: '\uC548\uC2DD\uC6D4',
  vacation7: '\uACF5\uAC00',
  vacation8: '\uACF5\uD734\uC77C',
  vacation9: '\uD734\uC77C',
  applicantTag: '\uC2E0\uCCAD\uC790:',
  componentTag: '\uBC1C\uAE09 \uBC1B\uC744 Component:',
  machineTag: '\uB77C\uC774\uC120\uC2A4 \uC778\uC99D \uB418\uB294 PC\uC758 MAC \uC8FC\uC18C \uB610\uB294 \uCEF4\uD4E8\uD130 \uC774\uB984:',
  productTag: '\uBC1C\uAE09 \uBC1B\uC744 \uC81C\uD488:',
  titleAlert: '\uD655\uC778\uC774 \uD544\uC694\uD55C \uB77C\uC774\uC120\uC2A4 \uC694\uCCAD \uBA54\uC77C\uC774 \uC788\uC2B5\uB2C8\uB2E4.',
  factRecipients: '\uC54C\uB9BC \uB300\uC0C1',
  factVacation: '\uD734\uAC00\uC790',
  factRequestCount: '\uB77C\uC774\uC120\uC2A4 \uC694\uCCAD',
  factApplicant: '\uBCF4\uB0B8\uC0AC\uB78C',
  factComponent: '\uBC1C\uD589\uC81C\uD488',
  factQuantity: '\uBC1C\uD589\uC218\uB7C9',
  factReceived: '\uC218\uC2E0\uC2DC\uAC01',
  linkText: '\uB77C\uC774\uC120\uC2A4 \uAD00\uB9AC \uD398\uC774\uC9C0\uB85C \uC774\uB3D9',
  none: '\uC5C6\uC74C',
  unknown: '\uD655\uC778 \uBD88\uAC00',
};

const people = [
  { name: '\uAE40\uC9C4\uC6B1', email: 'jwkim@vms-solutions.com' },
  { name: '\uAE40\uBBFC\uC601', email: 'mykim@vms-solutions.com' },
  { name: '\uC870\uD604\uC7AC', email: 'jyi30@vms-solutions.com' },
];

const recentWindowMs = 7 * 24 * 60 * 60 * 1000;
const fallbackManageUrl = "http://192.168.1.17/view/8B521E26-8B31-0EA5-0AC3-3B40CE4BDBAB/21616A03-5394-067D-BAFD-1F00637BFF9E/lms";

function normalize(value) { return String(value ?? '').normalize('NFC').replace(/\\s+/g, '').toLowerCase(); }
function contains(value, keyword) { return normalize(value).includes(normalize(keyword)); }
function arr(value) { return Array.isArray(value) ? value : []; }
function distinct(values) { return [...new Set(values.filter(Boolean))]; }
function isCompleted(flagStatus) { return flagStatus === 'complete' || flagStatus === 'completed'; }
function recent(row) { const ts = Date.parse(row?.receivedDateTime || ''); return Number.isFinite(ts) && ts >= (Date.now() - recentWindowMs); }
function alertable(row) { const status = row?.flag?.flagStatus ?? ''; return contains(row?.subject, K.approval) && (row?.isRead === false || (row?.isRead === true && !isCompleted(status))); }
function decode(html) {
  return String(html ?? '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#(\\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCodePoint(parseInt(code, 16)));
}
function htmlToText(html) {
  return decode(String(html ?? '')
    .replace(/<br[^>]*>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
    .replace(/\\r/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}
function getField(line, label) { const match = String(line ?? '').match(new RegExp(label + '\\s*:\\s*(.+)$', 'i')); return match ? match[1].trim() : ''; }
function parseEntries(html) {
  const blocks = htmlToText(html).split(/={5,}/).map((block) => block.trim()).filter(Boolean);
  const entries = [];
  for (const block of blocks) {
    const lines = block.split('\n').map((line) => line.trim()).filter(Boolean);
    const applicantLine = lines.find((line) => line.includes(K.applicantTag)) || '';
    const componentLine = lines.find((line) => line.includes(K.componentTag)) || '';
    const machineLine = lines.find((line) => line.includes(K.machineTag)) || '';
    const productLine = lines.find((line) => line.includes(K.productTag)) || '';
    const applicantMatch = applicantLine.match(/\uC2E0\uCCAD\uC790:\s*([^\)\]\s]+)/);
    const applicant = applicantMatch ? applicantMatch[1].trim() : '';
    const component = getField(componentLine, K.componentTag.replace(':', ''));
    const machine = getField(machineLine, K.machineTag.replace(':', ''));
    const product = getField(productLine, K.productTag.replace(':', ''));
    if (applicant || component || machine || product) entries.push({ applicant, component, machine, product });
  }
  return entries;
}
function extractManageUrl(html, webLink) {
  const match = String(html ?? '').match(/href="(http:\/\/192\.168\.1\.17[^"]+)"/i);
  return match ? match[1] : (fallbackManageUrl || webLink || '');
}
function toLocalString(isoString) {
  if (!isoString) return '';
  const date = new Date(isoString);
  if (Number.isNaN(date.getTime())) return String(isoString ?? '');
  const pad = (value) => String(value).padStart(2, "0");
  return date.getFullYear() + '-' + pad(date.getMonth() + 1) + '-' + pad(date.getDate()) + ' ' + pad(date.getHours()) + ':' + pad(date.getMinutes()) + ':' + pad(date.getSeconds()) + ' KST';
}
function mapCandidate(row) {
  const entries = parseEntries(row.body?.content || '');
  const applicants = distinct(entries.map((entry) => entry.applicant));
  const components = distinct(entries.map((entry) => entry.component));
  const machines = distinct(entries.map((entry) => entry.machine));
  const component = components[0] || '';
  const groupedMachines = component ? distinct(entries.filter((entry) => entry.component === component).map((entry) => entry.machine)) : machines;
  return {
    id: row.internetMessageId || row.id,
    subject: row.subject || '(no subject)',
    applicantText: applicants.join(', ') || row.from?.emailAddress?.name || row.from?.emailAddress?.address || K.unknown,
    productText: (component || components.join(', ') || K.unknown) + (entries[0]?.product ? ' (' + entries[0].product + ')' : ''),
    quantityText: String(groupedMachines.length || machines.length || 1),
    receivedDateTime: row.receivedDateTime || '',
    receivedText: toLocalString(row.receivedDateTime),
    manageUrl: extractManageUrl(row.body?.content || '', row.webLink || ''),
  };
}

const inboxRows = inboxPayload.error ? [] : arr(inboxPayload.value);
const folderRows = folderPayload.error ? [] : arr(folderPayload.value);

const inboxMatches = inboxRows
  .filter((row) => recent(row))
  .filter((row) => [K.license1, K.license2, K.license3].some((keyword) => contains((row.subject || '') + ' ' + (row.body?.content || '') + ' ' + (row.bodyPreview || ''), keyword)))
  .filter((row) => alertable(row))
  .map((row) => mapCandidate(row));

const folderMatches = folderRows
  .filter((row) => recent(row))
  .filter((row) => alertable(row))
  .map((row) => mapCandidate(row));

const deduped = [];
const seen = new Set();
for (const item of [...folderMatches, ...inboxMatches]) {
  const key = item.id || item.subject + '|' + item.receivedDateTime;
  if (seen.has(key)) continue;
  seen.add(key);
  deduped.push(item);
}
deduped.sort((a, b) => new Date(b.receivedDateTime || 0) - new Date(a.receivedDateTime || 0));

function collectStrings(value, out = [], depth = 0) {
  if (depth > 10 || value == null) return out;
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') { out.push(String(value)); return out; }
  if (Array.isArray(value)) { for (const item of value) collectStrings(item, out, depth + 1); return out; }
  if (typeof value === 'object') { for (const nested of Object.values(value)) collectStrings(nested, out, depth + 1); }
  return out;
}
function ymds(text) { return String(text ?? '').match(/\d{4}-\d{2}-\d{2}/g) || []; }
function ymd(text) { const match = String(text ?? '').match(/\d{4}-\d{2}-\d{2}/); return match ? match[0] : ''; }
function ranges(item) {
  const found = [];
  const uniq = new Set();
  function push(label, start, end) {
    const s = ymd(start);
    const e = ymd(end || start);
    if (!s) return;
    const key = label + '|' + s + '|' + e;
    if (uniq.has(key)) return;
    uniq.add(key);
    found.push({ start: s, end: e || s });
  }
  function walk(value, label, depth) {
    if (depth > 8 || value == null) return;
    if (typeof value === 'string') { const items = ymds(value); if (items.length === 1) push(label, items[0], items[0]); if (items.length >= 2) push(label, items[0], items[1]); return; }
    if (typeof value === 'number' || typeof value === 'boolean') return;
    if (Array.isArray(value)) { value.forEach((item, idx) => walk(item, label + "[" + idx + "]", depth + 1)); return; }
    if (typeof value === 'object') {
      if ('start' in value && ymd(value.start)) push(label + '.start', value.start, value.end || value.start);
      if ('date' in value && value.date && typeof value.date === 'object' && ymd(value.date.start)) push(label + '.date', value.date.start, value.date.end || value.date.start);
      if ('property_date' in value && value.property_date && typeof value.property_date === 'object' && ymd(value.property_date.start)) push(label + '.property_date', value.property_date.start, value.property_date.end || value.property_date.start);
      for (const [key, nested] of Object.entries(value)) walk(nested, label + "." + key, depth + 1);
    }
  }
  walk(item?.json ?? item, 'root', 0);
  return found;
}
function isVacationText(text) { return [K.vacation1, K.vacation2, K.vacation3, K.vacation4, K.vacation5, K.vacation6, K.vacation7, K.vacation8, K.vacation9, 'vacation', 'leave', 'pto', 'dayoff', 'off'].some((keyword) => contains(text, keyword)); }
const today = String(holiday.today_date || $('Weekday Baseline').first()?.json?.todayDate || '');
const isHoliday = !!holiday.is_holiday;
const vacationLookupFailed = vacationItems.some((item) => item?.json?.error);
const todayVacationItems = vacationLookupFailed ? [] : vacationItems.filter((item) => {
  const text = collectStrings(item?.json ?? item).join(" ");
  if (!isVacationText(text)) return false;
  const itemRanges = ranges(item);
  return itemRanges.length > 0 && itemRanges.some((range) => range.start <= today && today <= range.end);
});
const vacationUsers = people.filter((person) => todayVacationItems.some((item) => {
  const text = collectStrings(item?.json ?? item).join(" ");
  return contains(text, person.name) || contains(text, person.email);
}));
const vacationSet = new Set(vacationUsers.map((person) => person.email));
const activeUsers = people.filter((person) => !vacationSet.has(person.email));
const teamsEntities = activeUsers.map((person) => ({ type: "mention", text: "<at>" + person.name + "</at>", mentioned: { id: person.email, name: person.name } }));
const teamsText = activeUsers.map((person) => "<at>" + person.name + "</at>").join(", ");

const warningParts = [
  holiday.db_error ? "\uACF5\uD734\uC77C DB \uC870\uD68C \uC2E4\uD328: " + String(holiday.db_error) : "",
  folderInfo.folderError || (!folderInfo.folderFound ? "01. \uB77C\uC774\uC120\uC2A4 \uC694\uCCAD \uD3F4\uB354\uB97C \uCC3E\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4." : ""),
  inboxPayload.error?.message || inboxPayload.error?.description || inboxPayload.error || "",
  folderPayload.error?.message || folderPayload.error?.description || folderPayload.error || "",
  vacationLookupFailed ? "\uD734\uAC00 \uC815\uBCF4 \uC870\uD68C \uC2E4\uD328 \uC2DC \uAE30\uBCF8\uAC12(\uC804\uC6D0 \uADFC\uBB34)\uC73C\uB85C \uCC98\uB9AC\uD588\uC2B5\uB2C8\uB2E4." : "",
].filter(Boolean);

const alertCardBody = [];
if (!isHoliday && deduped.length > 0) {
  alertCardBody.push({ type: "TextBlock", text: teamsText ? "\uD83D\uDCEC " + teamsText + " \uB2D8, " + K.titleAlert : "\uD83D\uDCEC " + K.titleAlert, weight: "Bolder", size: "Medium", wrap: true });
  alertCardBody.push({ type: "FactSet", facts: [
    { title: K.factRecipients, value: activeUsers.length > 0 ? activeUsers.map((person) => person.name).join(", ") : K.none },
    { title: K.factVacation, value: vacationUsers.length > 0 ? vacationUsers.map((person) => person.name).join(", ") : K.none },
    { title: K.factRequestCount, value: String(deduped.length) + "\uAC74" },
  ] });
  alertCardBody.push({ type: "TextBlock", text: "-------------------------------------------------", wrap: true, spacing: "Medium", isSubtle: true });
  deduped.forEach((item, index) => {
    alertCardBody.push({ type: "TextBlock", text: item.subject, weight: "Bolder", wrap: true, spacing: index === 0 ? "Medium" : "Large" });
    alertCardBody.push({ type: "FactSet", facts: [
      { title: K.factApplicant, value: item.applicantText },
      { title: K.factComponent, value: item.productText },
      { title: K.factQuantity, value: item.quantityText },
      { title: K.factReceived, value: item.receivedText || item.receivedDateTime || K.unknown },
    ] });
    alertCardBody.push({ type: "TextBlock", text: "-------------------------------------------------", wrap: true, spacing: "Medium", isSubtle: true });
  });
  alertCardBody.push({ type: "TextBlock", text: "[" + K.linkText + "](" + ((deduped[0]?.manageUrl) || fallbackManageUrl) + ")", wrap: true, spacing: "Medium" });
  if (warningParts.length > 0) alertCardBody.push({ type: "TextBlock", text: warningParts.join(" / "), wrap: true, spacing: "Medium", color: "Attention" });
}

return [{ json: {
  alertCount: isHoliday ? 0 : deduped.length,
  teamsEntities,
  alertCardBody,
  debug: {
    isHoliday,
    holidayName: holiday.holiday_name || "",
    holidayLookupSource: holiday.holiday_lookup_source || "",
  },
} }];
